/* eslint-disable @typescript-eslint/ban-ts-comment */
import React from 'react';

import * as L from 'leaflet';
import 'leaflet-geometryutil';
import 'leaflet/dist/leaflet.css';

import '../../lib/leaflet-distance-markers/leaflet-distance-marker';
import '../../lib/leaflet-distance-markers/leaflet-distance-marker.css';

import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { getDivIcon, setMarkerObstacle } from '@apps/Routes/@helpers/leaflet.helper';
import { setMarkerSimpleIcon } from '@apps/Routes/@helpers/routeObjects.helper';
import { IBaseRouteObjectPoint, IMapType } from '@apps/Routes/@types/routes.types';
import ElevationChart from '@apps/Routes/RouteEditorNew/components/Elevation/ElevationChart';
import Summary from '@apps/Routes/RouteEditorNew/components/Summary';
import { formatAltitude, formatDistance } from '@helpers/formatHelper';
import { getForestTileLayer, getMap } from '@helpers/leafletHelper';
import { round } from '@helpers/mathHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import style from './style.module.less';

interface IPolylineInfoProps {
  height?: number | string;
  name?: string;
  summary?: boolean;
  points: Array<[number, number] | [number, number, number]>;
  secondaryPoints?: Array<[number, number, number]>;
  poi?: IBaseRouteObjectPoint[];
  mapType?: IMapType;
  timestamps?: number[];
  ref?: React.RefObject<L.Map | null>;
}

const PolylineInfo: React.FC<IPolylineInfoProps> = ({
  name,
  points,
  mapType,
  height = '900px',
  poi,
  summary = true,
  secondaryPoints,
  timestamps,
  ref: extMapRef,
}) => {
  const ref = React.useRef<HTMLDivElement>(null);
  const mapRef = extMapRef ?? React.useRef<L.Map>(null);
  const layerGroupRef = React.useRef<L.FeatureGroup>(null);
  const markerRef = React.useRef<L.Marker>(new L.Marker([0, 0], { icon: getDivIcon() }));

  React.useEffect(() => {
    if (!ref.current) return;
    if (!mapRef.current) {
      mapRef.current = getMap(ref.current as HTMLElement);

      mapType
        ? L.tileLayer(mapType.tileUrlTmpl).addTo(mapRef.current)
        : getForestTileLayer().addTo(mapRef.current);
      layerGroupRef.current = L.featureGroup().addTo(mapRef.current);
      watermarkToMap(mapRef.current);
    }
    if (!layerGroupRef.current) return;

    layerGroupRef.current.clearLayers();

    const pl = new L.Polyline(
      points.map((x) => {
        if (poi && layerGroupRef.current) {
          const targetPoi = poi.find(
            (p) =>
              round(x[0], 4) === round(p.coordinates[0], 4) &&
              round(x[1], 4) === round(p.coordinates[1], 4),
          );
          if (targetPoi) {
            const p = new L.Marker(targetPoi.coordinates);
            setMarkerSimpleIcon(p, targetPoi.color, !targetPoi.is_in_distance);
            targetPoi.obstacle && setMarkerObstacle(p, targetPoi.obstacle);
            p.addTo(layerGroupRef.current);
          }
        }

        return [x[0], x[1]];
      }),
      {
        //@ts-expect-error
        distanceMarkers: { offset: 1000, cssClass: style.kmPoint, iconSize: [16, 16] },
        color: '#ff0000',
        weight: 2,
        opacity: 1,
      },
    );

    if (name) {
      pl.bindTooltip(name);
      pl.bindPopup(name);
    }

    pl.addTo(layerGroupRef.current);

    const bounds = layerGroupRef.current?.getBounds();
    bounds.isValid() && mapRef.current.fitBounds(bounds);
    mapRef.current.scrollWheelZoom.disable();

    if (secondaryPoints) {
      const secondaryLine = new L.Polyline(
        secondaryPoints.map((x) => [x[0], x[1]]),
        {
          color: 'lime',
          weight: 2,
          opacity: 0.6,
          dashArray: [4, 4],
        },
      );

      secondaryLine.addTo(layerGroupRef.current);
    }
  }, []);

  return (
    <section>
      <div ref={ref} style={{ height }} />
      <PohRow>
        {summary && (
          <PohCol sm={2}>
            <Summary points={points as [number, number, number][]} />
          </PohCol>
        )}
        <PohCol sm={summary ? 10 : 12}>
          <ElevationChart
            points={points as [number, number, number][]}
            secondaryPoints={secondaryPoints}
            secondaryOptions={{
              color: 'lime',
              strokeWidth: 1,
            }}
            timestamps={timestamps}
            poi={poi}
            onCursorMove={(point, re) => {
              markerRef.current.setLatLng(point);
              markerRef.current.bindTooltip(formatAltitude(point[2]) + '<br>' + formatDistance(re));
              markerRef.current.openTooltip();
            }}
            onEndCursorMove={() => {
              mapRef.current && markerRef.current.removeFrom(mapRef.current);
            }}
            onStartCursorMove={() => {
              mapRef.current && markerRef.current.addTo(mapRef.current);
            }}
          />
        </PohCol>
      </PohRow>
    </section>
  );
};

export default PolylineInfo;
